create or replace function public.rehearsal_ops_bootstrap_superadmin(p_username text, p_password_hash text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('rehearsal-global-reset', 0));
  -- Serialize first-install bootstrap so two first logins cannot race.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('rehearsal_ops_bootstrap_superadmin', 0));
  -- Bootstrap only an empty installation. Existing DB accounts are canonical thereafter, so stale bootstrap env values are ignored.
  if exists (select 1 from public.rehearsal_ops_accounts where role = 'superadmin') then return; end if;
  if p_username is null or p_password_hash is null or p_username !~ '^[A-Z0-9_-]{1,80}$' or p_password_hash !~ '^scrypt\$[0-9a-f]{32}\$[0-9a-f]{64}$' then raise exception 'invalid bootstrap'; end if;
  insert into public.rehearsal_ops_accounts(username, role, display_label, password_hash, active) values (p_username, 'superadmin', '관리자', p_password_hash, true)
  on conflict (username) do nothing;
end; $$;
create or replace function public.rehearsal_ops_reserve_login(p_username text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare a public.rehearsal_ops_accounts%rowtype; v_now timestamptz := pg_catalog.now(); v_retry integer;
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('rehearsal-global-reset', 0));
  select * into a from public.rehearsal_ops_accounts where username = p_username for update;
  if not found or not a.active or a.password_hash is null then return jsonb_build_object('status','invalid'); end if;
  if a.failed_window_started_at is not null and a.failed_window_started_at > v_now - interval '15 minutes' and a.failed_attempts >= 12 then
    v_retry := greatest(1, ceil(extract(epoch from (a.failed_window_started_at + interval '15 minutes' - v_now)))::integer);
    return jsonb_build_object('status','limited','retryAfter',v_retry);
  end if;
  if a.failed_window_started_at is null or a.failed_window_started_at <= v_now - interval '15 minutes' then
    update public.rehearsal_ops_accounts set failed_attempts = 1, failed_window_started_at = v_now, updated_at = v_now where username = p_username;
  else
    update public.rehearsal_ops_accounts set failed_attempts = failed_attempts + 1, updated_at = v_now where username = p_username;
  end if;
  return jsonb_build_object('status','reserved','passwordHash',a.password_hash,'credentialVersion',a.credential_version);
end; $$;
create or replace function public.rehearsal_ops_finish_login(p_username text, p_success boolean, p_display_name text default null, p_session_label text default null, p_expires_at timestamptz default null, p_expected_credential_version integer default null)
