 if v_role is distinct from 'superadmin' then raise exception 'unauthorized' using errcode='42501'; end if;
 return (select coalesce(jsonb_agg(jsonb_build_object('username',username,'role',role,'displayLabel',display_label,'active',active,'hasPassword',password_hash is not null) order by username),'[]'::jsonb) from public.rehearsal_ops_accounts);
