create or replace function public.rehearsal_ops_upsert_account(p_session_id uuid, p_username text, p_role text, p_display_label text, p_password_hash text, p_active boolean)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_role text; a public.rehearsal_ops_accounts%rowtype; v_revoke boolean;
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('rehearsal-global-reset', 0));
 select actor.role into v_role from public.rehearsal_ops_sessions s join public.rehearsal_ops_accounts actor on actor.username=s.username where s.id=p_session_id and s.revoked_at is null and s.expires_at>now() and actor.active and actor.credential_version=s.credential_version for update of s,actor;
 if v_role is distinct from 'superadmin' then raise exception 'unauthorized' using errcode='42501'; end if;
 if p_username !~ '^[A-Z0-9_-]{1,80}$' or p_role not in ('parking','space') or char_length(p_display_label) not between 1 and 30 or (p_password_hash is not null and p_password_hash !~ '^scrypt\$[0-9a-f]{32}\$[0-9a-f]{64}$') then raise exception 'invalid account'; end if;
 select * into a from public.rehearsal_ops_accounts where username=p_username for update;
 if not found then
   if p_active and p_password_hash is null then raise exception 'active account requires password'; end if;
   insert into public.rehearsal_ops_accounts(username,role,display_label,password_hash,active) values(p_username,p_role,p_display_label,p_password_hash,p_active) returning * into a;
 else
   if a.role = 'superadmin' then raise exception 'superadmin account is immutable here' using errcode='42501'; end if;
   if p_active and coalesce(p_password_hash,a.password_hash) is null then raise exception 'active account requires password'; end if;
   v_revoke := p_password_hash is not null or a.active<>p_active or a.role<>p_role;
   update public.rehearsal_ops_accounts set role=p_role,display_label=p_display_label,password_hash=coalesce(p_password_hash,password_hash),active=p_active,credential_version=case when v_revoke then credential_version+1 else credential_version end,failed_attempts=case when p_password_hash is not null or (not a.active and p_active) then 0 else failed_attempts end,failed_window_started_at=case when p_password_hash is not null or (not a.active and p_active) then null else failed_window_started_at end,updated_at=now() where username=p_username returning * into a;
   if v_revoke then update public.rehearsal_ops_sessions set revoked_at=now() where username=p_username and revoked_at is null; end if;
 end if;
 return jsonb_build_object('username',a.username,'role',a.role,'displayLabel',a.display_label,'active',a.active,'hasPassword',a.password_hash is not null);
end; $$;
