create or replace function public.rehearsal_ops_reserve_login(p_username text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare account_row public.rehearsal_ops_accounts%rowtype; v_now timestamptz := pg_catalog.now(); v_window timestamptz; v_reservation uuid; v_retry integer;
begin
  perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('rehearsal-global-reset', 0));
  -- All functions that lock an account/session take this username key first.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('rehearsal-ops-account:' || coalesce(p_username, ''), 0));
  select * into account_row from public.rehearsal_ops_accounts where username = p_username for update;
  if not found or not account_row.active or account_row.password_hash is null then return jsonb_build_object('status','invalid'); end if;
  if account_row.failed_window_started_at is not null and account_row.failed_window_started_at > v_now - interval '15 minutes' and account_row.failed_attempts >= 12 then
    v_retry := greatest(1, ceil(extract(epoch from (account_row.failed_window_started_at + interval '15 minutes' - v_now)))::integer);
    return jsonb_build_object('status','limited','retryAfter',v_retry);
  end if;
  if account_row.failed_window_started_at is null or account_row.failed_window_started_at <= v_now - interval '15 minutes' then
    v_window := v_now;
    update public.rehearsal_ops_accounts set failed_attempts=1,failed_window_started_at=v_window,updated_at=v_now where username=p_username;
  else
    v_window := account_row.failed_window_started_at;
    update public.rehearsal_ops_accounts set failed_attempts=failed_attempts+1,updated_at=v_now where username=p_username;
  end if;
  insert into public.rehearsal_ops_login_reservations(username,credential_version,window_started_at) values(p_username,account_row.credential_version,v_window) returning id into v_reservation;
  return jsonb_build_object('status','reserved','passwordHash',account_row.password_hash,'credentialVersion',account_row.credential_version,'reservationId',v_reservation);
end; $$;

create function public.rehearsal_ops_finish_login(p_username text, p_reservation_id uuid, p_success boolean, p_display_name text default null, p_session_label text default null, p_expires_at timestamptz default null, p_expected_credential_version integer default null)
