-- estimate is intentional: older callers may still record available/busy/full
-- without fabricating a percentage.
create or replace function public.rehearsal_ops_set_resource_state(p_session_id uuid, p_resource_id text, p_state text, p_expected_version integer, p_request_id uuid, p_occupancy_percent integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_session_username text; v_role text; v_user text; v_label text; v_session_label text; resource_row public.rehearsal_ops_resources%rowtype; old_receipt public.rehearsal_ops_request_receipts%rowtype; result jsonb; v_before text; v_before_percent integer;
