  if not found or (v_role <> 'superadmin' and resource_row.category <> v_role) then raise exception 'unauthorized' using errcode='42501'; end if;
  if (resource_row.id='space.songrim.access' and p_state not in ('checking','closed','school_open','gym_open','hall_open','hall_closed')) or (resource_row.id<>'space.songrim.access' and p_state not in ('checking','closed','available','busy','full')) then raise exception 'invalid state'; end if;
  if resource_row.version<>p_expected_version then result:=jsonb_build_object('status','conflict','resource',jsonb_build_object('id',resource_row.id,'label',resource_row.label,'category',resource_row.category,'state',resource_row.state,'version',resource_row.version,'updatedAt',resource_row.updated_at,'occupancyPercent',resource_row.occupancy_percent,'lastClosedAt',resource_row.last_closed_at,'lastFullAt',resource_row.last_full_at));
  else
    v_before:=resource_row.state; v_before_percent:=resource_row.occupancy_percent;
    update public.rehearsal_ops_resources set state=p_state,occupancy_percent=p_occupancy_percent,version=version+1,updated_at=now(),
      last_closed_at=case when p_state in ('closed','hall_closed') and state is distinct from p_state then now() else last_closed_at end,
      last_full_at=case when p_state='full' and state is distinct from p_state then now() else last_full_at end where id=resource_row.id returning * into resource_row;
    insert into public.rehearsal_ops_history(resource_id,before_state,after_state,actor_username,actor_label,session_label,before_occupancy_percent,after_occupancy_percent) values(resource_row.id,v_before,p_state,v_user,v_label,v_session_label,v_before_percent,p_occupancy_percent);
    result:=jsonb_build_object('status','ok','resource',jsonb_build_object('id',resource_row.id,'label',resource_row.label,'category',resource_row.category,'state',resource_row.state,'version',resource_row.version,'updatedAt',resource_row.updated_at,'occupancyPercent',resource_row.occupancy_percent,'lastClosedAt',resource_row.last_closed_at,'lastFullAt',resource_row.last_full_at));
  end if;
  insert into public.rehearsal_ops_request_receipts(request_id,session_id,resource_id,state,expected_version,result,occupancy_percent) values(p_request_id,p_session_id,p_resource_id,p_state,p_expected_version,result,p_occupancy_percent);
  return result;
end; $$;

revoke all on function public.rehearsal_ops_set_resource_state(uuid,text,text,integer,uuid,integer) from public, anon, authenticated;
grant execute on function public.rehearsal_ops_set_resource_state(uuid,text,text,integer,uuid,integer) to service_role;


-- Replay 008_previous_day_parking.sql

-- Derive only observed transitions on the previous Korea calendar day.
-- A repeated full/closed check is not a new event. Initial checking -> closed
-- is not evidence that parking operated and then closed.
create or replace function public.rehearsal_ops_public_resources()
returns jsonb language sql stable security definer set search_path = '' as $$
 with bounds as (
  select (now() at time zone 'Asia/Seoul')::date as today
 ), previous as (
  select h.resource_id,
   min(h.created_at) filter(where h.after_state='full' and h.before_state<>'full') as first_full_at,
   max(h.created_at) filter(where h.after_state='closed' and h.before_state in ('available','busy','full')) as closed_at
  from public.rehearsal_ops_history h cross join bounds b
  where h.created_at >= (b.today-1)::timestamp at time zone 'Asia/Seoul'
    and h.created_at < b.today::timestamp at time zone 'Asia/Seoul'
  group by h.resource_id
 )
 select coalesce(jsonb_agg(jsonb_build_object(
  'id',r.id,'label',r.label,'category',r.category,'state',r.state,'version',r.version,
  'updatedAt',r.updated_at,'occupancyPercent',r.occupancy_percent,
  'lastClosedAt',r.last_closed_at,'lastFullAt',r.last_full_at
 ) || case when r.category='parking' then jsonb_build_object('previousDay',jsonb_build_object(
  'date',b.today-1,'firstFullAt',p.first_full_at,'closedAt',p.closed_at
 )) else '{}'::jsonb end order by r.id),'[]'::jsonb)
 from public.rehearsal_ops_resources r cross join bounds b left join previous p on p.resource_id=r.id;
$$;
revoke all on function public.rehearsal_ops_public_resources() from public,anon,authenticated;
grant execute on function public.rehearsal_ops_public_resources() to service_role;


-- Remove any bootstrap sample accounts before the ONE-TIME canonical copy.
delete from public.rehearsal_ops_accounts;
insert into public.rehearsal_ops_accounts(username,role,display_label,password_hash,active)
 select username,role,display_label,password_hash,active from public.ops_accounts;

create function public.rehearsal_ops_reset_rehearsal(p_session_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_username text; v_role text;
begin
 -- Global exclusive lock first: no mutation may cross a reset boundary.
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('rehearsal-global-reset', 0));
 select username into v_username from public.rehearsal_ops_sessions where id=p_session_id;
 if v_username is null then raise exception 'unauthorized' using errcode='42501'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('rehearsal-ops-account:' || v_username, 0));
 select a.role into v_role from public.rehearsal_ops_sessions s
 join public.rehearsal_ops_accounts a on a.username=s.username
 where s.id=p_session_id and s.username=v_username and s.revoked_at is null
 and s.expires_at>now() and a.active and a.credential_version=s.credential_version
 for update of s,a;
 if v_role is distinct from 'superadmin' then raise exception 'unauthorized' using errcode='42501'; end if;
 update public.rehearsal_ops_resources set state='checking',occupancy_percent=null,
 updated_at=null,last_closed_at=null,last_full_at=null,version=version+1;
 delete from public.rehearsal_ops_history;
 delete from public.rehearsal_ops_request_receipts;
 delete from public.rehearsal_community_v2_rates;
 delete from public.rehearsal_community_v2_audit;
 -- Keep path/token/payload tombstones indefinitely for late-upload cleanup and
 -- idempotent retries. Never remove storage.objects or return private paths.
 update public.rehearsal_community_v2_items set status='deleted',text='',event_day=null,
 ready=false,version=version+1,last_cleanup_at=null;
 return jsonb_build_object('reset',true);
end; $$;
revoke all on function public.rehearsal_ops_reset_rehearsal(uuid) from public,anon,authenticated;
grant execute on function public.rehearsal_ops_reset_rehearsal(uuid) to service_role;
commit;
